-- Senate rules harvested from courts' rozvrh práce (work schedule) documents
-- for 2026, covering all 94 okresní/obvodní/krajský/městský soud (VS/NS out of
-- scope). Complements the ISIR-based INS seed from 2026-07-18-01 with every
-- registry the schedules carry (T, C, Nc, P a Nc, EXE, INS, insolvency and
-- administrative-court registries, ...), including combinations that are NOT
-- discriminating (a senate number shared by dozens of courts) - the
-- resolver caller decides what candidate-list size is still useful.
--
-- Idempotent: INSERT IGNORE leaves the existing hand-curated ISIR rows (and
-- any row already present) untouched.
--
-- Sanity check after applying:
--   SELECT COUNT(*) FROM senate_rule;                    -- expect 8911
--   SELECT COUNT(*) FROM senate_rule WHERE note = 'Rozvrh práce 2026';  -- expect 8802

